        });
        let shell = app.state::<Shell>();
        let loaded = tauri::async_runtime::block_on(cycle_template(shell)).expect("the command answers");
        let names: Vec<&str> = loaded.lanes.iter().map(|lane| lane.name.as_str()).collect();
